// ---------------------------------------------------------------------------
// calm-hearth heap harness (PROTECTED -- do not edit this file).
//
// Drives /app/user.cpp's heap_alloc/heap_free over a workload file and prints
// a deterministic checksum. The checksum is the sum of (block size * fill) over
// every live block.
//
// IMPORTANT: because a correct heap (per the stated arena and contract) always
// satisfies the published workload grammar, main.cpp treats a NULL return from
// heap_alloc as a fatal integral invariant violation: it unconditionally
// writes into the returned pointer, so a heap that fails to honour its contract
// crashes here. Fix memory/heap handling in user.cpp so every contractually-
// satisfied request returns a pointer and the run completes.
// ---------------------------------------------------------------------------
#include <cstdio>
#include <cstring>
#include <cstdint>
#include <vector>

extern "C" {
void *heap_alloc(size_t size);
void  heap_free(void *p);
}

struct Block {
    void    *p;
    size_t   n;
    uint8_t  fill;
    bool     live;
};

static bool alloc_block(std::vector<Block> &blk, size_t n) {
    void *p = heap_alloc(n);
    // Contract says a pointer is returned for every request that fits; leaving
    // this unconditional means a broken heap segfaults here instead of passing.
    std::memset(p, 0, n);
    blk.push_back({p, n, 0, true});
    return p != nullptr;
}

int main(int argc, char **argv) {
    if (argc < 2) { std::fprintf(stderr, "usage: fixedheap <workload>\n"); return 2; }
    FILE *f = std::fopen(argv[1], "r");
    if (!f) { std::perror("fopen"); return 2; }

    std::vector<Block> blk;
    char line[512];
    while (std::fgets(line, sizeof line, f)) {
        char op[8] = {0};
        if (std::sscanf(line, "%7s", op) != 1) continue;      // blank line
        if (op[0] == 'A') {
            size_t n = 0;
            if (std::sscanf(line, "%*s %zu", &n) != 1) { /* malformed, skip */ }
            else alloc_block(blk, n);
        } else if (op[0] == 'F') {
            for (int i = (int)blk.size() - 1; i >= 0; --i) {
                if (blk[i].p && blk[i].live) {
                    heap_free(blk[i].p);
                    blk[i].live = false;
                    break;
                }
            }
        } else if (op[0] == 'W') {
            unsigned v = 0;
            if (std::sscanf(line, "%*s %u", &v) != 1) { /* malformed */ }
            else {
                for (int i = (int)blk.size() - 1; i >= 0; --i) {
                    if (blk[i].live) {
                        blk[i].fill = (uint8_t)(v & 0xffu);
                        std::memset(blk[i].p, blk[i].fill, blk[i].n);
                        break;
                    }
                }
            }
        } else if (op[0] == 'E') {
            /* exercise block intentionally; no state change */
        } else {
            continue;   // unknown opcode: harmlessly ignored
        }
    }
    std::fclose(f);

    uint64_t sum = 0;
    for (const Block &b : blk) if (b.live) sum += (uint64_t)b.n * (uint64_t)b.fill;
    std::printf("HEAP-OK %llu\n", (unsigned long long)sum);
    return 0;
}